.btn-next, .btn-submit {
    padding: 0.75rem 2rem;
    background: #4361ee;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-size: 1rem;
    cursor: pointer;
    margin-left: auto;
    transition: background 0.2s;
}

.btn-next:hover, .btn-submit:hover {
    background: #3451d1;
}

.btn-next:disabled, .btn-submit:disabled {
    background: #a0a0a0;
    cursor: not-allowed;
}

.btn-back {
    padding: 0.75rem 2rem;
    background: transparent;
    color: #666;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 1rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-back:hover {
    background: #f5f5f5;
    border-color: #999;
}

.btn-add {
    display: block;
    padding: 0.75rem 1.5rem;
    background: transparent;
